// === Tab: Shape ===
class Shape {
	constructor(pos, ang, s) {
		this.pos = pos;
		this.ang = ang;
		this.tang = createVector(ang.x, ang.y, ang.z);
		this.otang = createVector(ang.x, ang.y, ang.z);
		this.s = 0;
		this.ts = s;
		this.ots = s;
		this.tpos = createVector(pos.x, pos.y, pos.z);
		this.spikes = [];
		for(let i = 0; i<3; i++){
			this.spikes.push(p5.Vector.random3D())
		}
	}
	animate(){
		this.s = lerp(this.s, this.ts, 0.1);
		this.pos.lerp(this.tpos, 0.1);
		this.ang.lerp(this.tang, 0.1);
	}
	show() {
		push();
		rotateX(this.ang.x);
		translate(this.pos.y, this.pos.x, 0);
		rotateY(this.ang.y);
		rotateZ(this.ang.z);
		switch (shape) {
			case 0:
				box(this.s);
				break;
			case 1:
				cylinder(this.s / 2, this.s);
				break;
			case 2:
				torus(this.s / 2, this.s / 4);
				break;
			case 3:
				push();
				translate(0,0, this.s/1.5);
				box(this.s/1.5);
				pop();
				push();
				translate(0,0,-this.s/1.5);
				box(this.s/1.5);
				pop();
				break;
		}
		pop();
	}
}

