//For the #WCCChallenge, theme: "that sketch you never..."
let ang = 0;
let avel = 0;
let tip = 0;
let strobe = false;
let hue = 0;
let flash = 1;
let shape = 0;
let tree = 0;
let twist = 0;
let shapes = [];

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	rectMode(CENTER);
	colorMode(HSB, 360);
	makeShapes();
}

function makeShapes() {
	for (let a = 0; a < 150 * PI; a += 2.3999) { //Golden angle!
		let x, y;
		x = map(a, 0, 150 * PI, 0, height / 3);
		y = map(a, 0, 150 * PI, -height / 3, height / 3);
		let s = map(a, 0, 150 * PI, height / 48, height / 16);
		let pos = createVector(x, y, 0);
		var ang = createVector(a, -a / 150, a / 150);
		shapes.push(new Shape(pos, ang, s));
	}
}

function draw() {
	background(0);
	ambientLight(0, 0, 180);
	if (strobe) {
		flash = 1 - flash;
		pointLight(0, 0, 180 * flash, -height / 8, -height, height); 
		pointLight(hue, 320, 180 * flash, height / 8, -height, height); 
	} else {
		pointLight(0, 0, 200, height / 8, -height, height); 
	}
	specularMaterial(200, 0, 180); 
	rect(-3 * width / 8, 0, width / 180, height);
	rect(3 * width / 8, 0, width / 180, height);
	tip = lerp(tip, map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, PI, -PI), 0.1);
	rotateX(tip);
	rotateZ(HALF_PI);
	ang += avel;
	if (frameCount > 60) {
		avel = lerp(avel, map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, -1, 1), 0.05);
		if (abs((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2) < width / 10) avel *= 0.9;
	}
	rotateX(ang);
	noStroke();
	for (let s of shapes) {
		s.show();
		s.animate();
	}
}

function mousePressed() {
	strobe = !strobe;
	hue = random(360);
}

function keyPressed() {
	if (keyCode == 65) {
		twist = (twist + 1) % 5;
		shiftAngle();
	}
	if (keyCode == 83) {
		for (let s of shapes) {
			s.ts = 0;
		}
		setTimeout(shiftShape, 400);
	}
	if (keyCode == 84) {
		tree = (tree + 1) % 4;
		shiftTree();
	}
	if (keyCode == 68) {
		hue = random(360); 
	}
	if (keyCode == 32) {
		hue = random(360); 
		strobe = true;
		tree = (tree + 1) % 4;
		shiftTree();
		for (let s of shapes) {
			s.ts = 0;
		}
		twist = (twist + 1) % 5;
		shiftAngle();
		setTimeout(shiftShape, 400);
	}
}

function shiftTree() {
	switch (tree) {
		case 0:
			for (let s of shapes) {
				s.ts = s.ots;
				s.tpos.x = map(s.otang.x, 0, 150 * PI, 0, height / 3);
				s.tpos.y = map(s.otang.x, 0, 150 * PI, -height / 3, height / 3);
			}
			break;
		case 1:
			for (let s of shapes) {
				let ax = map(s.otang.x, 0, 150 * PI, 0, HALF_PI);
				s.tpos.x = (height / 3) * sin(ax);
				s.tpos.y = map(s.otang.x, 0, 150 * PI, -height / 3, height / 3);
			}
			break;
		case 2:
			for (let s of shapes) {
				var ax = map(s.otang.x, 0, 150 * PI, 0, HALF_PI);
				s.tpos.x = (height / 3) * sin(ax);
				let ay = map(s.otang.x, 0, 150 * PI, 0, HALF_PI);
				s.tpos.y = height / 4 + (height / 2) * -cos(ay);
			}
			break;
		case 3:
			for (let s of shapes) {
				var ax = map(s.otang.x, 0, 150 * PI, 0, HALF_PI);
				s.tpos.x = (height / 3) * sin(2 * ax);
				var ay = map(s.otang.x, 0, 150 * PI, 0, HALF_PI);
				s.tpos.y = (height / 3) * -cos(2 * ay);
				s.ts = (height / 48) + ((height / 32) * sin(2 * ax));
			}
			break;
	}
}

function shiftShape() {
	shape = (shape + 1) % 3;
	for (let s of shapes) {
		if (tree == 3) {
			var ax = map(s.otang.x, 0, 150 * PI, 0, HALF_PI);
			s.ts = (height / 48) + ((height / 32) * sin(2 * ax));
		} else {
			s.ts = s.ots;
		}
	}
}

function shiftAngle() {
	for (let s of shapes) {
		switch (twist) {
			case 0:
				s.tang = createVector(s.otang.x, s.otang.y, s.otang.z);
				break;
			case 1:
				s.tang.y = 2.399;
				s.tang.z = 0;
				break;
			case 2:
				s.tang.y = 0;
				s.tang.z = -2.399;
				break;
			case 3:
				s.tang.y = 2.399;
				s.tang.z = -2.399;
				break;
			case 4:
				s.tang.y = 0;
				s.tang.z = 0;
				break;
		}
	}
}
